const REFRESH_MS=20*60*1000,fmt=n=>new Intl.NumberFormat("en-IN").format(Math.round(n)),stamp=s=>new Date(s).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"});
const style=document.createElement("link");style.rel="stylesheet";style.href="suggestions.css";document.head.appendChild(style);const theme=document.createElement("link");theme.rel="stylesheet";theme.href="theme-v2.css";document.head.appendChild(theme);
async function load(){try{const r=await fetch(`suggestions.json?t=${Date.now()}`,{cache:"no-store"}),payload=await r.json();if(!r.ok||payload.error)throw new Error();const videos=Array.isArray(payload)?payload:payload.videos||[];videos.sort((a,b)=>b.vph-a.vph);document.getElementById("trendRows").innerHTML=videos.map(v=>`<tr><td><div class="trend-video"><img src="${v.thumb}" alt=""><div><b>${v.title}</b><span>${v.channel}</span></div></div></td><td><b>${fmt(v.views)}</b></td><td><span class="velocity">↑ ${fmt(v.vph)}</span></td><td><span class="score">${v.momentum.toFixed(1)}×</span></td><td><a class="watch-link" href="https://youtu.be/${v.id}" target="_blank" rel="noopener">Watch ↗</a></td></tr>`).join("");document.getElementById("ideaGrid").innerHTML=videos.slice(0,5).map((v,i)=>`<article class="idea"><b>${["🔥","🚀","✨","🎵","💡"][i]} ${v.title}</b><span>${fmt(v.vph)} views/hour · ${v.momentum.toFixed(1)}× current momentum. Create an original Adhyesha version.</span></article>`).join("");document.getElementById("trendSync").innerHTML=`<i></i> YouTube trends · ${stamp(payload.syncedAt||new Date())}`}catch{document.getElementById("trendSync").textContent="Trend data unavailable · retrying automatically"}}
const menu=document.getElementById("menuBtn"),side=document.getElementById("sidebar"),scrim=document.getElementById("scrim");menu.onclick=()=>{side.classList.toggle("open");scrim.classList.toggle("open")};scrim.onclick=()=>{side.classList.remove("open");scrim.classList.remove("open")};document.querySelector(".sidebar nav")?.insertAdjacentHTML("beforeend",'<a href="reports.html">▦ <span>Advanced reports</span></a><a href="planner.html">✓ <span>Content planner</span></a>');load();setInterval(load,REFRESH_MS);
